// Referee: single-file build. Generated by tools/bundle.mjs. Edit the sources, not this file.
// ===== packages/decimal/decimal.mjs =====
// Exact decimal arithmetic on BigInt. No floats anywhere in the emissions or money path.
// A Dec is (u, s): value = u / 10^s, s >= 0. Rounding is always explicit and defaults to HALF_UP (away from zero).

const pow10 = (n) => 10n ** BigInt(n);

function divRound(n, d, mode = 'HALF_UP') {
  if (d === 0n) throw new RangeError('division by zero');
  const neg = (n < 0n) !== (d < 0n);
  const N = n < 0n ? -n : n;
  const D = d < 0n ? -d : d;
  let q = N / D;
  const r = N % D;
  if (mode === 'HALF_UP') { if (r * 2n >= D) q += 1n; }
  else if (mode !== 'DOWN') throw new RangeError(`unknown rounding mode ${mode}`);
  return neg ? -q : q;
}

class Dec {
  constructor(u, s = 0) {
    this.u = BigInt(u);
    this.s = s;
    Object.freeze(this);
  }

  static from(x) {
    if (x instanceof Dec) return x;
    if (typeof x === 'bigint') return new Dec(x, 0);
    if (typeof x === 'number') {
      if (!Number.isInteger(x)) throw new TypeError('floating-point numbers are rejected; pass a decimal string');
      return new Dec(BigInt(x), 0);
    }
    if (typeof x === 'string') {
      const m = /^(-?)(\d+)(?:\.(\d+))?$/.exec(x.trim());
      if (!m) throw new TypeError(`not a decimal string: ${JSON.stringify(x)}`);
      const frac = m[3] || '';
      return new Dec(BigInt(m[1] + m[2] + frac), frac.length);
    }
    throw new TypeError(`cannot convert ${typeof x} to Dec`);
  }

  _align(o) {
    const s = Math.max(this.s, o.s);
    return [this.u * pow10(s - this.s), o.u * pow10(s - o.s), s];
  }

  add(o) { o = Dec.from(o); const [a, b, s] = this._align(o); return new Dec(a + b, s); }
  sub(o) { o = Dec.from(o); const [a, b, s] = this._align(o); return new Dec(a - b, s); }
  mul(o) { o = Dec.from(o); return new Dec(this.u * o.u, this.s + o.s); }

  // Division to `scale` decimal places (default 30), rounded per `mode`.
  div(o, scale = 30, mode = 'HALF_UP') {
    o = Dec.from(o);
    const num = this.u * pow10(o.s + scale);
    const den = o.u * pow10(this.s);
    return new Dec(divRound(num, den, mode), scale);
  }

  neg() { return new Dec(-this.u, this.s); }
  cmp(o) { o = Dec.from(o); const [a, b] = this._align(o); return a < b ? -1 : a > b ? 1 : 0; }
  eq(o) { return this.cmp(o) === 0; }
  lt(o) { return this.cmp(o) < 0; }
  gt(o) { return this.cmp(o) > 0; }
  isZero() { return this.u === 0n; }

  round(places, mode = 'HALF_UP') {
    if (this.s <= places) return new Dec(this.u * pow10(places - this.s), places);
    return new Dec(divRound(this.u, pow10(this.s - places), mode), places);
  }

  // Exact string; toFixed(p) rounds first so the string always has exactly p decimals.
  toString() {
    if (this.s === 0) return this.u.toString();
    const neg = this.u < 0n;
    const digits = (neg ? -this.u : this.u).toString().padStart(this.s + 1, '0');
    const int = digits.slice(0, digits.length - this.s);
    const frac = digits.slice(digits.length - this.s);
    return `${neg ? '-' : ''}${int}.${frac}`;
  }
  toFixed(places, mode = 'HALF_UP') { return this.round(places, mode).toString(); }
}

const D = (x) => Dec.from(x);

// ===== packages/engine/trace.mjs =====
// Every calculation step returns a Trace node. The trace is built DURING the calculation, never reconstructed afterwards.
function node({ id, label, value, unit, formula, inputs = [], citations = [], note }) {
  return { id, label, value: value.toString(), unit, formula, inputs, citations, ...(note ? { note } : {}) };
}
const leaf = (id, label, value, unit, source) => ({ id, label, value: value.toString(), unit, source });

// ===== packages/engine/calc.mjs =====
// Pure calculation primitives for specific embedded emissions (SEE). No I/O, no globals.

const GUIDANCE3 = 'Guidance No. 3 (non-binding), equations 61-62; legal basis IR 2025/2547 attribution and precursor rules';

// Eq. 61: m_i = M_i / AL_g  (precursor mass consumed per tonne of product)
function precursorMassRatio({ id, consumedT, activityLevelT }) {
  const value = D(consumedT).div(D(activityLevelT), 30);
  return node({
    id, label: 'Precursor specific mass m_i', value, unit: 't precursor / t product', formula: 'm_i = M_i / AL_g (Eq. 61)',
    inputs: [leaf(`${id}.M`, 'Precursor consumed M_i', consumedT, 't/yr', 'operator data'), leaf(`${id}.AL`, 'Activity level AL_g', activityLevelT, 't/yr', 'operator data')],
    citations: [GUIDANCE3],
  });
}

// Direct emissions per tonne of product from fuel energy: GJ/t x (t CO2/TJ) / 1000
function directFromEnergy({ id, energyGJPerT, efTCO2PerTJ, factorRef }) {
  const value = D(energyGJPerT).mul(D(efTCO2PerTJ)).div(1000, 30);
  return node({
    id, label: 'Own direct emissions per tonne of product', value, unit: 't CO2 / t product',
    formula: 'energy [GJ/t] x emission factor [t CO2/TJ] / 1000',
    inputs: [leaf(`${id}.E`, 'Energy intensity', energyGJPerT, 'GJ/t product', 'operator data'), leaf(`${id}.EF`, 'Emission factor', efTCO2PerTJ, 't CO2/TJ', factorRef)],
    citations: [factorRef],
  });
}

// Eq. 62: SEE_g = own direct per tonne + sum(m_i x SEE_i)
function seeComplexGood({ id, own, precursors }) {
  let total = D(own.value);
  const parts = [own];
  for (const p of precursors) {
    const term = D(p.ratio.value).mul(D(p.see));
    parts.push(node({
      id: `${id}.${p.name}`, label: `Precursor term: ${p.name}`, value: term, unit: 't CO2 / t product', formula: 'm_i x SEE_i',
      inputs: [p.ratio, leaf(`${id}.${p.name}.SEE`, `SEE of ${p.name}`, p.see, 't CO2 / t precursor', p.seeSource)],
      citations: [GUIDANCE3],
    }));
    total = total.add(term);
  }
  return node({ id, label: 'Specific embedded emissions (direct)', value: total, unit: 't CO2e / t product', formula: 'SEE_g = own direct + sum(m_i x SEE_i) (Eq. 62)', inputs: parts, citations: [GUIDANCE3] });
}

// Reporting precision: IR 2025/2547 Annex II rule 8 - all significant digits, maximum 5 digits after the comma.
const reportSEE = (dec) => dec.toFixed(5);

// ===== packages/engine/lookup.mjs =====
// Lookups over the law snapshot. Fail closed: ambiguity returns a refusal object, never a guess.

const SECTOR_KEY = { 'Iron and steel': 'iron_and_steel', Cement: 'cement', Aluminium: 'aluminium', Hydrogen: 'hydrogen', Fertilisers: 'fertilisers' };

function findInCountry(table, cn) {
  if (!table) return { status: 'no_table' };
  for (let len = cn.length; len >= 4; len--) {            // exact code, then shorter legal prefixes (4-6 digit entries cover all 8-digit codes)
    const rec = table[cn.slice(0, len)];
    if (rec) return { status: 'found', record: rec };
  }
  const longer = Object.keys(table).filter((k) => k.startsWith(cn));   // table holds 10-digit TARIC rows under this code
  if (longer.length === 1) return { status: 'found', record: table[longer[0]] };
  if (longer.length > 1) return { status: 'ambiguous', candidates: longer.map((k) => table[k]) };
  return { status: 'not_found' };
}

function lookupDefault(snap, country, cn) {
  const own = findInCountry(snap.defaults.countries[country], cn);
  if (own.status === 'ambiguous') return { refused: 'ambiguous CN code: supply the full TARIC code', candidates: own.candidates.map((r) => r.cn_display) };
  if (own.status === 'found' && own.record.total !== null) return { record: own.record, basis: { country, fallbackToOther: false } };
  const other = findInCountry(snap.defaults.countries.OTHER, cn);
  if (other.status === 'found' && other.record.total !== null) {
    return { record: other.record, basis: { country: 'OTHER', fallbackToOther: true, requestedCountry: country, reason: own.status === 'found' ? 'country value blank or marked' : 'country or code not listed' } };
  }
  return { refused: 'no default value found', basis: { country, cn } };
}

function markupRate(snap, sector, year) {
  const key = SECTOR_KEY[sector];
  if (!key) throw new RangeError(`unknown sector ${sector}`);
  if (key === 'fertilisers') return D(snap.markups.fertilisers['2026+']);
  const m = snap.markups.sectors[key];
  return D(year <= 2026 ? m['2026'] : year === 2027 ? m['2027'] : m['2028+']);
}

// Exact marked-up default. Rounding of this figure is computed by the CBAM Registry (open question O1), so none is applied here.
function markedUpDefault(snap, record, year) {
  const rate = markupRate(snap, record.sector, year);
  return D(record.total).mul(D(1).add(rate));
}

function lookupBenchmark(snap, cn8) {
  const rec = snap.benchmarks.records[cn8];
  return rec ? { record: rec } : { refused: 'benchmark not found for this 8-digit CN code' };
}

function fuelFactor(snap, name) {
  const rec = snap.factors.tables.table_1.records.find((r) => r.name === name);
  if (!rec) return { refused: `fuel not in Table 1: ${name}` };
  return { ef: D(rec.ef_t_co2_per_tj), ncv: D(rec.ncv_tj_per_gg), ref: snap.factors.tables.table_1.legal_ref };
}

// ===== packages/engine/sefa.mjs =====
// Free-allocation side of the CBAM obligation (Guidance No. 4 equations 1, 2, 4, 6; legal basis IR 2025/2620).

const G4 = 'Guidance No. 4 (non-binding); legal basis IR 2025/2620 (free allocation adjustment)';

function yearFactors(snap, year) {
  const y = String(year);
  const cbam = snap.cbamFactor.years[y];
  const c = snap.cbamFactor.cscf_by_year[y];
  if (cbam === undefined || !c) return { refused: `no CBAM factor for ${year}` };
  return { cbam: D(cbam), cscf: D(c.value), cscfFinal: c.status === 'set', cscfStatus: c.status === 'set' ? `set by ${c.ref}` : `PRELIMINARY: ${c.ref}`, ref: snap.cbamFactor.legal_ref };
}

const factorLeaves = (id, f) => [leaf(`${id}.cbam`, 'CBAM factor', f.cbam, '', f.ref), leaf(`${id}.cscf`, 'CSCF', f.cscf, '', `${f.cscfStatus}`)];

// Eq. 2: SFA_proc = CBAM_y x CSCF_y x BM*_g   (actual-data route, Column A benchmark)
function sfaProc({ id, bmStar, f }) {
  const value = f.cbam.mul(f.cscf).mul(D(bmStar));
  return node({ id, label: 'Process specific free allocation', value, unit: 't CO2 / t', formula: 'SFA_proc = CBAM_y x CSCF_y x BM*_g (Eq. 2)',
    inputs: [...factorLeaves(id, f), leaf(`${id}.bm`, 'Process benchmark BM* (Column A)', bmStar, 't CO2 / t', 'IR 2025/2620 annex section 5, Column A')], citations: [G4] });
}

// Eq. 4: SEFA_g = SFA_proc + sum(m_i x SEFA_i)
function sefaComplex({ id, sfa, precursors }) {
  let total = D(sfa.value);
  const parts = [sfa];
  for (const p of precursors) {
    total = total.add(D(p.ratio.value).mul(D(p.sefa)));
    parts.push(p.ratio, leaf(`${id}.${p.name}.sefa`, `SEFA of ${p.name}`, p.sefa, 't CO2 / t precursor', p.source));
  }
  return node({ id, label: 'Specific embedded free allocation', value: total, unit: 't CO2 / t', formula: 'SEFA_g = SFA_proc + sum(m_i x SEFA_i) (Eq. 4)', inputs: parts, citations: [G4] });
}

// Eq. 6: SEFA_g = CBAM_y x CSCF_y x BM_g   (default route, Column B benchmark)
function sefaDefault({ id, bmChain, f }) {
  const value = f.cbam.mul(f.cscf).mul(D(bmChain));
  return node({ id, label: 'Default specific embedded free allocation', value, unit: 't CO2 / t', formula: 'SEFA_g = CBAM_y x CSCF_y x BM_g (Eq. 6)',
    inputs: [...factorLeaves(id, f), leaf(`${id}.bm`, 'Chain benchmark BM (Column B)', bmChain, 't CO2 / t', 'IR 2025/2620 annex section 5, Column B')], citations: [G4] });
}

// Certificates to surrender (before any carbon price deduction): SEE x M - SEFA x M. Negative results are shown as zero.
function certificateObligation({ id, see, sefa, massT }) {
  const emb = D(see).mul(D(massT));
  const faa = D(sefa).mul(D(massT));
  const raw = emb.sub(faa);
  const value = raw.lt(0) ? D(0) : raw;
  return node({ id, label: 'CBAM certificates (estimate, before carbon-price deduction)', value, unit: 'certificates (t CO2e)',
    formula: 'N = SEE x M - FAA, FAA = SEFA x M; negative shown as 0 (see open question O7)',
    inputs: [leaf(`${id}.embedded`, 'Embedded emissions SEE x M', emb, 't CO2e', 'see inputs'), leaf(`${id}.faa`, 'Free allocation adjustment FAA', faa, 't CO2e', 'see inputs')],
    citations: [G4], note: raw.lt(0) ? `raw value ${raw.toString()} was negative` : undefined });
}

// ===== packages/engine/exposure.mjs =====
// Importer exposure: default path versus the supplier's actual values. Pure; the caller supplies a loaded snapshot.

function pickChainBenchmark(variants, route, year) {
  const vs = variants.map((v) => v.col_b).filter((b) => b.value !== null);
  if (vs.length === 1) return { value: vs[0].value, route: vs[0].route };
  const byRoute = route ? vs.filter((b) => b.route === route) : [];
  if (byRoute.length === 1) return { value: byRoute[0].value, route: byRoute[0].route };
  if (year > 2030) return { refused: 'year-dependent benchmark values are only defined to 2030' };
  const code = year <= 2027 ? '(1)' : '(2)';
  const byYear = vs.filter((b) => b.route === code);
  if (byYear.length === 1) return { value: byYear[0].value, route: byYear[0].route };
  return { refused: 'benchmark is ambiguous for this route and year' };
}

function exposureCase(snap, { country, cn8, year, massT, priceEur, actual }) {
  const notes = ['Estimate for decision support. Prepared for verification; not a verification statement.'];
  if (!/^\d{8}$/.test(cn8)) return { refused: 'enter the 8-digit CN code' };
  const f = yearFactors(snap, year);
  if (f.refused) return { refused: f.refused };
  const def = lookupDefault(snap, country, cn8);
  if (def.refused) return { refused: def.refused };
  const rec = def.record;
  const bm = lookupBenchmark(snap, cn8);
  if (bm.refused) return { refused: bm.refused };
  const chain = pickChainBenchmark(bm.record.variants, rec.route, year);
  if (chain.refused) return { refused: chain.refused };

  const seeDefault = markedUpDefault(snap, rec, year);
  const rate = markupRate(snap, rec.sector, year);
  const seeNode = node({ id: 'default.see', label: 'Default SEE including mark-up', value: seeDefault, unit: 't CO2e / t',
    formula: 'SEE_default = total emissions default x (1 + mark-up)',
    inputs: [leaf('default.total', `Default total emissions (${def.basis.country})`, rec.total, 't CO2e / t', `IR 2026/1740, ${rec.source.sheet} row ${rec.source.row} (workbook); CN ${rec.cn_display}`), leaf('default.markup', 'Mark-up', rate, '', snap.markups.legal_ref)],
    citations: [snap.markups.legal_ref] });
  const sefaNode = sefaDefault({ id: 'default.sefa', bmChain: chain.value, f });
  const certDefault = certificateObligation({ id: 'default.cert', see: seeDefault, sefa: sefaNode.value, massT });
  const out = { snapshot: snap.id, inputs: { country, cn8, year, massT, priceEur: priceEur ?? null },
    default: { country: def.basis.country, fallbackToOther: def.basis.fallbackToOther, route: rec.route, chainBenchmark: chain, see: seeNode, sefa: sefaNode, certificates: certDefault },
    notes };
  if (def.basis.fallbackToOther) notes.push(`Country value not listed or blank: "Other countries and territories" default used (${def.basis.reason}).`);
  if (!f.cscfFinal) notes.push(`CSCF for ${year} is not yet published; the preliminary 1.0 is used.`);
  notes.push('Mark-up rounding is performed by the CBAM Registry; the exact figure is shown.');
  if (priceEur) out.default.cost = D(certDefault.value).mul(D(priceEur)).toString();

  if (actual && actual.see !== undefined && actual.see !== '') {
    const sefaActual = actual.sefa !== undefined && actual.sefa !== '' ? actual.sefa : null;
    if (sefaActual === null) notes.push('No supplier SEFA entered: actual path not calculated. Enter the SEFA from the supplier report.');
    else {
      const certActual = certificateObligation({ id: 'actual.cert', see: actual.see, sefa: sefaActual, massT });
      out.actual = { see: actual.see, sefa: sefaActual, certificates: certActual };
      const diff = D(certDefault.value).sub(D(certActual.value));
      out.saving = { certificates: diff.toString() };
      if (priceEur) { out.actual.cost = D(certActual.value).mul(D(priceEur)).toString(); out.saving.eur = diff.mul(D(priceEur)).toString(); }
      notes.push('Actual values count only if verified by an accredited verifier; this tool does not verify.');
    }
  }
  return out;
}

// ===== packages/engine/decide.mjs =====
// Verify-or-default: what an accredited verification must save to pay for itself, year by year.
// Free allocation differs by route: the actual route earns SFA_proc (Column A) plus precursor allocations, the default route earns the Column B chain benchmark.
// With the supplier's SEFA the answer is exact. Without it, two bounds are shown: same SEFA as the default, and process-only (no precursor allocation).
// Price, tonnes and verification cost are the caller's inputs, held constant across years. Nothing is estimated here.
const DECIDE_YEARS = [2026, 2027, 2028, 2029, 2030];

function processSefa(snap, cn8, year, chainRoute) {      // Eq. 2 with the Column A benchmark; null when none is published for this route
  const v = lookupBenchmark(snap, cn8).record.variants.find((x) => x.col_b.route === chainRoute);
  return v && v.col_a.value ? sfaProc({ id: 'proc', bmStar: v.col_a.value, f: yearFactors(snap, year) }).value : null;
}

function verifyOrDefault(snap, { country, cn8, massT, priceEur, verifyEur, supplierSee, sefaActual }) {
  const P = D(priceEur), M = D(massT), V = D(verifyEur);
  if (!P.gt(0) || !M.gt(0)) return { refused: 'price and tonnes must be above zero' };
  const rows = [];
  for (const year of DECIDE_YEARS) {
    const r = exposureCase(snap, { country, cn8, year, massT, priceEur });
    if (r.refused) { if (rows.length === 0) return { refused: r.refused }; rows.push({ year, refused: r.refused }); continue; }
    const see = D(r.default.see.value), sefaD = D(r.default.sefa.value), certs = D(r.default.certificates.value), ceiling = certs.mul(P);
    const proc = sefaActual ? null : processSefa(snap, cn8, year, r.default.chainBenchmark.route);
    const defs = sefaActual ? [['supplier SEFA', D(sefaActual)]] : [['same SEFA as default', sefaD], ...(proc ? [['process-only SEFA', D(proc)]] : [])];
    const canPay = V.lt(ceiling);
    const scen = defs.map(([label, sefa]) => {
      const s = { label, sefa, breakEven: null };
      if (canPay) s.breakEven = node({ id: `breakeven.${year}`, label: `Break-even supplier SEE ${year} (${label})`, value: see.sub(V.div(P.mul(M), 12)).sub(sefaD.sub(sefa)), unit: 't CO2e / t',
        formula: 'SEE* = default SEE - V / (P x M) - (SEFA_default - SEFA_actual)',
        inputs: [leaf('be.see', 'Default SEE incl. mark-up', see, 't CO2e / t', 'default path trace'), leaf('be.sefad', 'SEFA on the default path', sefaD, 't CO2e / t', 'default path trace'),
          leaf('be.sefaa', `SEFA on the actual path (${label})`, sefa, 't CO2e / t', sefaActual ? 'supplier report' : 'Guidance No. 4, Eq. 2 and Eq. 6'),
          leaf('be.v', 'Verification cost V (your input)', V, 'EUR per year', 'your input'), leaf('be.p', 'Certificate price P (your input)', P, 'EUR per t CO2e', 'your input'), leaf('be.m', 'Mass M (your input)', M, 't per year', 'your input')],
        citations: ['Arithmetic on the default path (IR 2026/1740 defaults, mark-up) and the free allocation of Guidance No. 4; V, P and M are your inputs'] });
      if (supplierSee) { const raw = D(supplierSee).sub(sefa).mul(M); s.saving = certs.sub(raw.lt(0) ? D(0) : raw).mul(P); s.net = s.saving.sub(V); }
      return s;
    });
    rows.push({ year, see, sefa: sefaD, certs, cost: ceiling, trace: r.default, canPay, scen, swing: scen.length > 1 ? abs(scen[0].sefa.sub(scen[1].sefa)).mul(M).mul(P) : null });
  }
  return { snapshot: snap.id, inputs: { country, cn8, massT, priceEur, verifyEur, supplierSee: supplierSee || null, sefaActual: sefaActual || null }, rows,
    notes: ['Without the supplier\'s SEFA, free allocation is shown as two bounds. Ask the supplier for the SEFA: it can matter as much as the verification cost.',
      'Price, tonnes and verification cost are your inputs and are held constant across years. Nothing is estimated for you.',
      'Actual values count only if verified by an accredited verifier; this tool does not verify.'] };
}

// ===== packages/engine/browser-loader.mjs =====
// Loads the single-file data bundle through an injected fetchJson(url), so the same code runs in browsers and in Node tests.
async function loadWebSnapshot(fetchJson, url = 'data.json') {
  const data = await fetchJson(url);
  const names = Object.keys(data.defaults.countries).filter((c) => c !== 'OTHER').sort((a, b) => a.localeCompare(b));
  return { ...data, countryIndex: names.map((name) => ({ name })) };
}

// Kept for API compatibility: every country is already in memory.
async function ensureCountry(snap, name) {
  return Boolean(snap.defaults.countries[name]);
}

// ===== packages/audit/data.mjs =====
// Static lists and sample reports for the supplier-report audit. Sources noted per list.

// EU Member States (precursors originating in the Union count as zero embedded emissions: Guidance No. 2, section 3, precursors).
const EU27 = ['Austria', 'Belgium', 'Bulgaria', 'Croatia', 'Cyprus', 'Czechia', 'Czech Republic', 'Denmark', 'Estonia', 'Finland', 'France', 'Germany', 'Greece', 'Hungary', 'Ireland', 'Italy', 'Latvia', 'Lithuania', 'Luxembourg', 'Malta', 'Netherlands', 'Poland', 'Portugal', 'Romania', 'Slovakia', 'Slovenia', 'Spain', 'Sweden'];
// Exempted countries: Annex III point 1 to Regulation (EU) 2023/956 (as listed in Guidance No. 4, footnote 11).
const EXEMPT = ['Iceland', 'Liechtenstein', 'Norway', 'Switzerland'];

// What an importer should have received. Points refer to Annex IV, point 1.1 of IR 2025/2547 (operator's emissions report) unless stated.
const CHECKLIST = [
  { id: 'c1', text: 'Operator and installation identification, incl. CBAM Registry installation ID', ref: 'Annex IV 1.1 point 1' },
  { id: 'c2', text: 'Summary of the installation monitoring plan', ref: 'Annex IV 1.1 point 2' },
  { id: 'c3', text: 'Total direct emissions of the installation', ref: 'Annex IV 1.1 point 7' },
  { id: 'c4', text: 'Goods produced and quantities per production process', ref: 'Annex IV 1.1 point 13' },
  { id: 'c5', text: 'SEE per good and the share based on default values', ref: 'Annex IV 1.1 point 15(a),(d)' },
  { id: 'c6', text: 'Precursor quantities and data (actual or default)', ref: 'Annex IV 1.1 points 20-23' },
  { id: 'c7', text: 'Data gaps and estimates disclosed', ref: 'Annex IV 1.1 point 16(e)' },
  { id: 'c8', text: 'Verification report with a positive opinion attached', ref: 'Guidance No. 2, section 6' },
  { id: 'c9', text: 'Carbon price paid information', ref: 'Guidance No. 2, step 6' },
];

const allChecked = Object.fromEntries(CHECKLIST.map((c) => [c.id, true]));

// Clean sample: the Commission's own Example 3 numbers (Guidance 5d). Origin and report reference are illustrative.
const SAMPLE_CLEAN = {
  meta: { label: 'Official Example 3 (Guidance 5d), carbon-steel screws and nuts', synthetic: false },
  verification: { opinion: 'positive', accreditation: 'confirmed', sectorCovered: 'yes' },
  good: { cn8: '73181520', originCountry: 'Algeria', route: '(C)', reportingYear: '2026', importYear: '2026', activityLevelT: '17000', fuel: 'Natural gas', energyGJperT: '3.5', seeDirectReported: '2.039', seeIndirectReported: '', sefaReported: '' },
  precursor: { present: true, consumedT: '20000', seeReported: '1.567', source: 'verified', originCountry: 'Algeria', verificationRef: 'ILLUSTRATIVE-ROD-2026-001', periodYear: '2026', mReported: '1.176' },
  aluminium: { scrapPerT: '', preConsumerPct: '', alloyPct: '' },
  checklist: allChecked,
  case: { reference: 'SAMPLE-001', importer: 'Example Importer GmbH (illustrative)', supplier: 'Example Rod Mill (illustrative)', preparedBy: '', massT: '100', priceEur: '80' },
};

// Synthetic flawed sample: SAME inputs, with deliberate errors injected so you can see what the audit flags. Not a real report.
const SAMPLE_FLAWED = {
  meta: { label: 'SYNTHETIC flawed report (errors injected on purpose)', synthetic: true },
  verification: { opinion: 'qualified', accreditation: 'unknown', sectorCovered: 'unknown' },
  good: { cn8: '73181520', originCountry: 'Algeria', route: '(X)', reportingYear: '2025', importYear: '2026', activityLevelT: '17000', fuel: 'Natural gas', energyGJperT: '3.5', seeDirectReported: '2.1500000', seeIndirectReported: '0.310', sefaReported: '' },
  precursor: { present: true, consumedT: '20000', seeReported: '1.567', source: 'verified', originCountry: 'Germany', verificationRef: '', periodYear: '2025', mReported: '1.05' },
  aluminium: { scrapPerT: '', preConsumerPct: '', alloyPct: '' },
  checklist: { ...allChecked, c2: false, c5: false, c8: false, c9: false },
  case: { reference: 'SAMPLE-002 (synthetic)', importer: 'Example Importer GmbH (illustrative)', supplier: 'Example Rod Mill (illustrative)', preparedBy: '', massT: '100', priceEur: '80' },
};

// ===== packages/audit/rules.mjs =====
// Supplier-report audit. Every finding has a legal or guidance basis; no invented thresholds except where labelled as an assumption.

const G2 = 'Guidance No. 2 (non-binding)';
const finding = (id, severity, title, detail, citation) => ({ id, severity, title, detail, citation });
const isNum = (s) => /^\d+(\.\d+)?$/.test(String(s ?? '').trim());
const decimals = (s) => (String(s).split('.')[1] || '').length;
const abs = (d) => (d.lt(0) ? d.neg() : d);
const tolerance = (reported) => D('1.5').div(D(10 ** decimals(reported)), 12);   // ASSUMPTION: up to 3 rounded steps, 0.5 unit each, in the last reported decimal

function auditReport(snap, r) {
  const out = [];
  const v = r.verification || {}, g = r.good || {}, p = r.precursor || {};
  const year = Number(g.reportingYear), importYear = Number(g.importYear);

  // Verification status: actual values count only if verified by an accredited verifier (Guidance 2, section 6)
  if (v.opinion === 'positive') out.push(finding('VER-1', 'pass', 'Verification opinion is positive', 'Actual values can be considered.', `${G2}, section 6`));
  else if (v.opinion === 'qualified' || v.opinion === 'negative') out.push(finding('VER-1', 'fail', `Verification opinion is ${v.opinion}`, 'Actual values are eligible only if verified. Ask for a corrected report or fall back to default values.', `${G2}, section 6`));
  else out.push(finding('VER-1', 'warn', 'Verification opinion not confirmed', 'Obtain the verification report and confirm the opinion.', `${G2}, section 6`));
  if (v.accreditation === 'confirmed' && v.sectorCovered === 'yes') out.push(finding('VER-2', 'pass', 'Verifier accreditation confirmed for the sector', '', `${G2}, section 6`));
  else if (v.accreditation === 'not_confirmed' || v.sectorCovered === 'no') out.push(finding('VER-2', 'fail', 'Verifier accreditation not valid for this sector', 'The verifier needs accreditation from an EU National Accreditation Body, valid when the final report is issued and covering the installation sector.', `${G2}, section 6`));
  else out.push(finding('VER-2', 'warn', 'Verifier accreditation not confirmed', 'Check the accreditation certificate and its sector scope with the issuing National Accreditation Body.', `${G2}, section 6`));

  // Reporting period: calendar year, not before 2026; for goods imported in 2026 it is 2026 (Guidance 2, step 2)
  if (!Number.isInteger(year) || year < 2026) out.push(finding('PER-1', 'fail', 'Reporting period is before 2026 or missing', 'In the definitive period the reporting period is a calendar year and cannot be earlier than 2026.', `${G2}, step 2`));
  else if (importYear === 2026 && year !== 2026) out.push(finding('PER-1', 'warn', 'Reporting period differs from the import year', 'For goods imported in 2026 the reporting period is 2026.', `${G2}, step 2`));
  else if (Number.isInteger(importYear) && year !== importYear) out.push(finding('PER-1', 'info', 'Reporting period differs from the import year', 'Allowed when evidence shows the actual production time; ask for that evidence.', `${G2}, step 2`));
  else out.push(finding('PER-1', 'pass', 'Reporting period consistent', '', `${G2}, step 2`));

  // Precision (IR 2025/2547 Annex II rule 8: at most 5 digits after the comma)
  for (const [label, val] of [['SEE', g.seeDirectReported], ['indirect SEE', g.seeIndirectReported], ['SEFA', g.sefaReported]]) {
    if (isNum(val) && decimals(val) > 5) out.push(finding('PRE-1', 'warn', `Reported ${label} has more than 5 decimals`, `"${val}" is outside the reporting precision rule: all significant digits, at most 5 after the comma.`, 'IR 2025/2547, Annex II (rounding rules)'));
  }

  // Recompute SEE (Eq. 61-62) and reconcile
  let recompute = null, radar = null;
  if (isNum(g.activityLevelT) && p.present && isNum(p.consumedT) && isNum(p.seeReported) && !D(g.activityLevelT).isZero()) {
    const ratio = precursorMassRatio({ id: 'm', consumedT: p.consumedT, activityLevelT: g.activityLevelT });
    let own = null;
    if (isNum(g.ownDirectPerT)) own = node({ id: 'own', label: 'Own direct emissions per tonne (as reported)', value: D(g.ownDirectPerT), unit: 't CO2 / t product', formula: 'as reported by the supplier', inputs: [leaf('own.in', 'Reported value', g.ownDirectPerT, 't CO2 / t', 'supplier report')], citations: ['supplier report'] });
    else if (isNum(g.energyGJperT)) {
      const fuel = fuelFactor(snap, g.fuel || 'Natural gas');
      if (!fuel.refused) own = directFromEnergy({ id: 'own', energyGJPerT: g.energyGJperT, efTCO2PerTJ: fuel.ef.toString(), factorRef: fuel.ref });
    }
    if (own) {
      const see = seeComplexGood({ id: 'see', own, precursors: [{ name: 'precursor', ratio, see: p.seeReported, seeSource: p.verificationRef || 'supplier report' }] });
      recompute = { see, ratio, own };
      const total = D(see.value);
      const term = D(ratio.value).mul(D(p.seeReported));
      radar = [
        { name: 'Precursor supplier SEE', contribution: term, share: term.div(total, 6), breakEven: D(5).mul(total).div(term, 6) },
        { name: 'Precursor mass ratio m', contribution: term, share: term.div(total, 6), breakEven: D(5).mul(total).div(term, 6) },
        { name: 'Own direct emissions', contribution: D(own.value), share: D(own.value).div(total, 6), breakEven: D(5).mul(total).div(D(own.value), 6) },
      ].sort((a, b) => a.breakEven.cmp(b.breakEven));
      if (isNum(g.seeDirectReported)) {
        const diff = abs(D(g.seeDirectReported).sub(total));
        const rel = diff.div(total, 6);
        if (diff.lt(tolerance(g.seeDirectReported)) || diff.eq(tolerance(g.seeDirectReported))) out.push(finding('SEE-1', 'pass', 'Reported SEE reproduces within rounding', `Recomputed ${total.toFixed(5)}; reported ${g.seeDirectReported}.`, 'Guidance No. 3, Eq. 61-62'));
        else if (rel.gt('0.05')) out.push(finding('SEE-1', 'fail', 'Reported SEE does not reproduce: material difference', `Recomputed ${total.toFixed(5)} versus reported ${g.seeDirectReported} (${rel.mul(100).toFixed(1)}%, above the 5% materiality level). Ask the supplier to reconcile.`, 'Guidance No. 3, Eq. 61-62; IR 2025/2546 (5% materiality)'));
        else out.push(finding('SEE-1', 'warn', 'Reported SEE differs from the recomputation beyond rounding', `Recomputed ${total.toFixed(5)} versus reported ${g.seeDirectReported} (${rel.mul(100).toFixed(2)}%): below materiality, but ask what explains it.`, 'Guidance No. 3, Eq. 61-62'));
      } else out.push(finding('SEE-1', 'info', 'No reported SEE to reconcile', `Recomputed ${total.toFixed(5)} t CO2e/t.`, 'Guidance No. 3, Eq. 61-62'));
      if (isNum(p.mReported)) {
        const dm = abs(D(p.mReported).sub(D(ratio.value)));
        if (dm.gt(tolerance(p.mReported))) out.push(finding('SEE-2', 'warn', 'Reported precursor mass ratio differs from consumed / produced', `Computed ${D(ratio.value).toFixed(5)} versus reported ${p.mReported}.`, 'Guidance No. 3, Eq. 61'));
      }
    }
  } else out.push(finding('SEE-1', 'info', 'SEE not recomputed', 'Enter activity level, precursor data and own energy to recompute.', 'Guidance No. 3, Eq. 61-62'));

  // Precursor evidence (Guidance 2, step 3, precursors)
  if (p.present) {
    if (p.source === 'verified') {
      if (!String(p.verificationRef || '').trim()) out.push(finding('PRE-2', 'fail', 'Precursor marked verified but no verification report referenced', 'A valid positive verification report covering the relevant year is needed and must be kept in the records.', `${G2}, step 3 (precursors)`));
      else out.push(finding('PRE-2', 'pass', 'Precursor verification report referenced', p.verificationRef, `${G2}, step 3 (precursors)`));
      const py = Number(p.periodYear);
      if (!Number.isInteger(py) || py < 2026) out.push(finding('PRE-3', 'fail', 'Precursor period is before 2026 or missing', '', `${G2}, step 3 (precursors)`));
      else if (Number.isInteger(year) && py !== year) out.push(finding('PRE-3', 'warn', 'Precursor period differs from the complex good period', 'By default the precursor period is the production year of the complex good, unless evidence shows the actual production time.', `${G2}, step 3 (precursors)`));
    } else if (p.source === 'default') out.push(finding('PRE-2', 'info', 'Precursor uses default values', 'Default values include the mark-up. A verified supplier report can lower the figure.', `${G2}, step 3 (precursors)`));
    const o = String(p.originCountry || '').trim();
    if ((EU27.includes(o) || EXEMPT.includes(o)) && isNum(p.seeReported) && !D(p.seeReported).isZero()) out.push(finding('PRE-4', 'warn', `Precursor from ${o} carries emissions`, 'Precursors from the Union or exempted countries count as zero embedded emissions, but their quantities must still be reported.', `${G2}, step 3 (precursors)`));
  }

  // Direct-only goods, route, default comparison
  const def = g.originCountry && /^\d{8}$/.test(String(g.cn8 || '')) ? lookupDefault(snap, g.originCountry, g.cn8) : null;
  if (def && def.record) {
    const rec = def.record;
    if (rec.indirect == null && rec.markers && rec.markers.indirect === 'N/A' && isNum(g.seeIndirectReported) && !D(g.seeIndirectReported).isZero()) out.push(finding('IND-1', 'warn', 'Indirect emissions reported for a direct-only good', 'For goods listed in Annex II to the CBAM Regulation only direct emissions count; indirect emissions are not included in embedded emissions.', `${G2}, step 3; Reg. (EU) 2023/956 Annex II`));
    if (isNum(g.seeDirectReported) && isNum(rec.total)) {
      const unmarked = D(rec.total), marked = markedUpDefault(snap, rec, Number.isInteger(importYear) ? importYear : 2026);
      const pct = D(g.seeDirectReported).div(unmarked, 6).mul(100).toFixed(0);
      out.push(finding('DEF-1', D(g.seeDirectReported).gt(marked) ? 'warn' : 'info', D(g.seeDirectReported).gt(marked) ? 'Reported SEE is higher than the marked-up default' : 'Reported SEE compared with the default', `Reported ${g.seeDirectReported}; default ${unmarked.toString()} (${marked.toFixed(3)} with mark-up): reported is ${pct}% of the unmarked default. Not a pass/fail test: use it to decide what evidence to ask for.`, 'IR 2026/1740 (default values and mark-up)'));
    }
  }
  const bm = /^\d{8}$/.test(String(g.cn8 || '')) ? lookupBenchmark(snap, g.cn8) : null;
  if (bm && bm.record) {
    const routes = new Set(bm.record.variants.flatMap((x) => [x.col_a.route, x.col_b.route]).filter(Boolean));
    if (g.route && routes.size && !routes.has(g.route)) out.push(finding('ROU-1', 'warn', `Production route ${g.route} is not recognised for this CN code`, `Known route or year codes: ${[...routes].join(', ')}.`, 'Guidance No. 4, Table 2-2'));
    else if (!g.route && [...routes].some((x) => /^\([C-L]\)$/.test(x))) out.push(finding('ROU-1', 'warn', 'Production route missing', 'The route decides which benchmark applies to the free-allocation adjustment.', 'Guidance No. 4, Table 2-2'));
  }

  // Sector-specific parameters (aluminium: Guidance 5e, Table 3-4)
  if (String(g.cn8 || '').startsWith('76')) {
    const a = r.aluminium || {};
    if (!isNum(a.scrapPerT) || !isNum(a.preConsumerPct) || a.alloyPct === undefined || a.alloyPct === '') out.push(finding('ALU-1', 'warn', 'Aluminium report parameters missing', 'Scrap used per tonne, share of pre-consumer scrap, and alloy content when other elements exceed 1%.', 'Guidance No. 5e, Table 3-4'));
  }

  if (!isNum(g.sefaReported)) out.push(finding('SFA-1', 'info', 'SEFA not provided', 'Needed for the free-allocation adjustment. Ask the supplier for it, or use default benchmarks.', 'Guidance No. 4'));

  // Completeness checklist (what an importer should have received)
  const cl = r.checklist || {};
  const missing = CHECKLIST.filter((c) => cl[c.id] !== true);
  for (const c of missing) out.push(finding(`CHK-${c.id}`, 'warn', `Not received: ${c.text}`, '', c.ref));

  const order = { fail: 0, warn: 1, info: 2, pass: 3 };
  out.sort((a, b) => order[a.severity] - order[b.severity]);
  const count = (s) => out.filter((x) => x.severity === s).length;
  const summary = { fail: count('fail'), warn: count('warn'), info: count('info'), pass: count('pass'), received: CHECKLIST.length - missing.length, checklistTotal: CHECKLIST.length };
  summary.verdict = summary.fail > 0 ? 'Do not rely on these values as actual values yet: resolve the failed checks or fall back to default values.'
    : summary.warn > 0 ? 'No failed checks, but follow up the warnings before relying on the values.' : 'No issues found by these checks. This is not a verification.';
  return { findings: out, summary, recompute, radar, label: (r.meta && r.meta.label) || '', synthetic: Boolean(r.meta && r.meta.synthetic), snapshot: snap.id };
}

// ===== packages/audit/render.mjs =====
// HTML rendering of an audit result. Everything user-supplied is escaped. Used by the web app and by the sample-pack generator.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const BADGE = { fail: 'FAIL', warn: 'WARN', info: 'INFO', pass: 'PASS' };

function traceHtml(n) {
  if (!n.inputs) return `<li>${esc(n.label)}: ${esc(n.value)} ${esc(n.unit)} <small>(source: ${esc(n.source)})</small></li>`;
  return `<li><strong>${esc(n.label)}</strong>: ${esc(n.value)} ${esc(n.unit)}<br><small>${esc(n.formula)}${(n.citations || []).map((c) => ' · basis: ' + esc(c)).join('')}</small><ul>${n.inputs.map(traceHtml).join('')}</ul></li>`;
}

function renderAuditBody(res) {
  const s = res.summary;
  const rows = res.findings.map((f) => `<tr class="sev-${f.severity}"><td><span class="badge b-${f.severity}">${BADGE[f.severity]}</span></td><td><strong>${esc(f.title)}</strong>${f.detail ? `<br>${esc(f.detail)}` : ''}</td><td>${esc(f.citation)}</td></tr>`).join('');
  let calc = '<p class="note">SEE was not recomputed (inputs missing).</p>';
  if (res.recompute) {
    const { see, ratio, own } = res.recompute;
    calc = `<table><tr><th>Recomputed SEE (legal precision)</th><td class="num">${esc(fixed5(see.value))}</td></tr>
<tr><th>Precursor mass ratio m</th><td class="num">${esc(trim(ratio.value, 5))}</td></tr>
<tr><th>Own direct per tonne</th><td class="num">${esc(trim(own.value, 5))}</td></tr></table>
<details><summary>Show the full trace</summary><ul class="trace">${traceHtml(see)}</ul></details>`;
  }
  const radar = res.radar ? `<table><tr><th>Input</th><th>Share of SEE</th><th>Error that would move SEE by 5%</th></tr>${res.radar.map((r) => `<tr><td>${esc(r.name)}</td><td class="num">${esc(r.share.mul(100).toFixed(1))}%</td><td class="num">${esc(r.breakEven.toFixed(1))}%</td></tr>`).join('')}</table>
<p class="note">5% is the materiality level used by verifiers. A small error in the rows at the top is enough to matter: ask for evidence there first.</p>` : '<p class="note">Radar needs a recomputation.</p>';
  return `${res.synthetic ? '<p class="synthetic">SYNTHETIC EXAMPLE: errors were injected on purpose. This is not a real supplier report.</p>' : ''}
<h2>Supplier report audit</h2><p class="note">${esc(res.label)} · law snapshot ${esc(res.snapshot)}</p>
<div class="verdict v-${s.fail ? 'fail' : s.warn ? 'warn' : 'pass'}"><strong>${esc(s.verdict)}</strong><br>${s.fail} failed · ${s.warn} warnings · ${s.info} notes · ${s.pass} passed · ${s.received} of ${s.checklistTotal} expected items received</div>
<h3>Findings</h3><table class="findings"><tr><th></th><th>Check</th><th>Basis</th></tr>${rows}</table>
<h3>Recomputation</h3>${calc}
<h3>Materiality radar</h3>${radar}
<p class="note">Prepared for verification. This audit does not verify anything: only an accredited verifier verifies. Independent reproduction of public rules, not an official tool. Not legal advice.</p>`;
}

function trim(v, places) { const [i, f = ''] = String(v).split('.'); return f ? `${i}.${f.slice(0, places)}` : i; }
function fixed5(v) { const [i, f = ''] = String(v).split('.'); const digits = (f + '000000').slice(0, 6); const n = BigInt(i + digits.slice(0, 5)) + (digits[5] >= '5' ? 1n : 0n); const s = n.toString().padStart(6, '0'); return `${s.slice(0, -5)}.${s.slice(-5)}`; }

function renderAuditDocument(res) {
  const css = `body{font:14px/1.45 system-ui,Segoe UI,Roboto,sans-serif;color:#14213d;margin:24px;max-width:820px}h2{margin:0 0 4px}h3{margin:18px 0 6px}table{border-collapse:collapse;width:100%;margin:6px 0}th,td{border:1px solid #d8dde6;padding:6px 8px;text-align:left;vertical-align:top}th{background:#f1f4fa}.num{text-align:right;font-variant-numeric:tabular-nums}.note{color:#5a6478;font-size:12px}.badge{font-weight:700;font-size:11px;padding:2px 6px;border-radius:4px;color:#fff}.b-fail{background:#b42318}.b-warn{background:#b54708}.b-info{background:#475467}.b-pass{background:#067647}.verdict{padding:10px;border-radius:8px;margin:10px 0}.v-fail{background:#fdeaea}.v-warn{background:#fff6dd}.v-pass{background:#e7f6ee}.synthetic{background:#14213d;color:#fff;padding:8px;border-radius:6px;font-weight:700}ul.trace{font-size:12px;padding-left:18px}small{color:#5a6478}`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Supplier report audit</title><style>${css}</style></head><body>${renderAuditBody(res)}</body></html>`;
}

// ===== packages/audit/requests.mjs =====
// Turns findings into a concrete evidence request list and a ready-to-send supplier email.

const MAP = {
  'VER-1': "A copy of the full verification report including the verifier's opinion statement.",
  'VER-2': "The verifier's accreditation certificate and scope annex from an EU National Accreditation Body, valid on the report date and covering the installation's sector.",
  'PER-1': 'Production records showing the actual production period of the goods, or a report for the correct reporting year.',
  'PRE-1': 'A corrected report with values rounded to at most 5 decimals.',
  'SEE-1': 'The calculation workbook behind the reported SEE: activity data, calculation factors, attribution between processes and precursor inputs.',
  'SEE-2': 'The purchase records and production log used to derive the precursor mass ratio.',
  'PRE-2': "The precursor supplier's verification report (valid, positive opinion, covering the relevant year) and its reference number.",
  'PRE-3': "Evidence of the precursor's actual production period.",
  'PRE-4': "Confirmation of the precursor's origin, and whether it was produced in the EU or an exempted country (counted as zero).",
  'IND-1': 'Confirmation that indirect emissions are excluded for this good, or a corrected report.',
  'DEF-1': 'An explanation, with supporting data, of why the reported value is above the marked-up default.',
  'ROU-1': 'The production route used at the installation (for example blast furnace/BOF, DRI/EAF or scrap/EAF) and how it maps to the benchmark.',
  'ALU-1': 'The aluminium report parameters: scrap used per tonne, pre-consumer scrap share and alloy content.',
  'SFA-1': 'The reported specific embedded free allocation (SEFA) for the good.',
};
for (const c of CHECKLIST) MAP[`CHK-${c.id}`] = `${c.text} (${c.ref}).`;

function evidenceRequests(res) {
  const seen = new Set();
  const out = [];
  for (const f of res.findings) {
    if (!['fail', 'warn'].includes(f.severity) && f.id !== 'SFA-1') continue;
    const text = MAP[f.id];
    if (text && !seen.has(text)) { seen.add(text); out.push({ id: f.id, severity: f.severity, text }); }
  }
  return out;
}

function supplierEmail({ requests, reference, importer, supplier, preparedBy }) {
  if (!requests.length) return 'No evidence requests: none of the checks needs follow-up.';
  const list = requests.map((r, i) => `${i + 1}. ${r.text}`).join('\n');
  return `Subject: CBAM data request${reference ? ` (${reference})` : ''}

Dear ${supplier || 'colleague'},

We have reviewed the CBAM emissions report you provided${importer ? ` for ${importer}` : ''}. To use your actual values in our CBAM declaration, we need the following:

${list}

Under the CBAM rules, actual values can be used only if they are verified by an accredited verifier. Without them we must use the default values, which include a mark-up.

Kind regards,
${preparedBy || '[your name]'}`;
}

// ===== packages/audit/fingerprint.mjs =====
// Tamper-evident fingerprint: SHA-256 of the canonical JSON of the inputs plus the law snapshot id.
const canon = (v) => (Array.isArray(v) ? `[${v.map(canon).join(',')}]` : v && typeof v === 'object' ? `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${canon(v[k])}`).join(',')}}` : JSON.stringify(v));

async function fingerprint(input, snapshotId) {
  const bytes = new TextEncoder().encode(canon({ input, snapshot: snapshotId }));
  const digest = await globalThis.crypto.subtle.digest('SHA-256', bytes);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

// ===== packages/audit/pdf.mjs =====
// Client-ready PDF "Supplier Report Audit Pack". Layout only: every number comes from the audit result passed in.
// PDFLib (pdf-lib, MIT) is injected so the same code runs in the browser and in Node tests.
const A4 = [595.28, 841.89];
const M = 46;
const COL = { ink: [0.08, 0.13, 0.24], mute: [0.35, 0.4, 0.5], line: [0.84, 0.87, 0.91], fail: [0.71, 0.14, 0.09], warn: [0.71, 0.28, 0.03], info: [0.28, 0.33, 0.4], pass: [0.03, 0.46, 0.28],
  failBg: [0.99, 0.92, 0.92], warnBg: [1, 0.96, 0.87], passBg: [0.91, 0.96, 0.93], head: [0.94, 0.96, 0.98], navy: [0.08, 0.13, 0.24] };
const SEV = { fail: 'FAIL', warn: 'WARN', info: 'INFO', pass: 'PASS' };

// WinAnsi-safe text for the standard PDF fonts.
function clean(s) {
  return String(s ?? '').replace(/₂/g, '2').replace(/≥/g, '>=').replace(/≤/g, '<=').replace(/→/g, '->').replace(/×/g, 'x').replace(/[‐-―]/g, '-')
    .replace(/\u00A0/g, ' ').replace(/[^\x09\x0A\x0D\x20-\x7E\u00A1-\u00FF€•…‘’“”–—]/g, '?');
}
const fmt5 = (v) => { const [i, f = ''] = String(v).split('.'); const d = (f + '000000').slice(0, 6); const n = BigInt(i + d.slice(0, 5)) + (d[5] >= '5' ? 1n : 0n); const s = n.toString().padStart(6, '0'); return `${s.slice(0, -5)}.${s.slice(-5)}`; };
const grp = (s) => s.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const money = (dec) => { const [i, f = ''] = String(dec).split('.'); const n = BigInt(i) * 100n + BigInt(((f + '00').slice(0, 2))) + ((f + '000')[2] >= '5' ? 1n : 0n); const s = n.toString().padStart(3, '0'); return `EUR ${grp(s.slice(0, -2))}.${s.slice(-2)}`; };

async function buildAuditPdf(PDFLib, res, ctx) {
  const { PDFDocument, StandardFonts, rgb } = PDFLib;
  const pdf = await PDFDocument.create();
  pdf.setTitle('Supplier Report Audit Pack');
  pdf.setProducer('Referee');
  pdf.setCreator('Referee');
  const reg = await pdf.embedFont(StandardFonts.Helvetica);
  const bold = await pdf.embedFont(StandardFonts.HelveticaBold);
  const col = (c) => rgb(...c);
  const W = A4[0] - 2 * M;
  let page, y;

  const newPage = () => { page = pdf.addPage(A4); y = A4[1] - M - 8; };
  const ensure = (h) => { if (y - h < M + 26) newPage(); };
  const wrap = (text, font, size, width) => {
    const lines = [];
    for (const para of clean(text).split('\n')) {
      let line = '';
      for (const word of para.split(/\s+/).filter(Boolean)) {
        const t = line ? `${line} ${word}` : word;
        if (font.widthOfTextAtSize(t, size) <= width) line = t;
        else {
          if (line) lines.push(line);
          let w = word;                               // hard-break very long tokens
          while (font.widthOfTextAtSize(w, size) > width) { let k = w.length; while (k > 1 && font.widthOfTextAtSize(w.slice(0, k), size) > width) k--; lines.push(w.slice(0, k)); w = w.slice(k); }
          line = w;
        }
      }
      lines.push(line);
    }
    return lines;
  };
  const text = (str, { size = 10, font = reg, color = COL.ink, x = M, width = W, lead = 1.35, gap = 0 } = {}) => {
    const lines = wrap(str, font, size, width);
    for (const l of lines) { ensure(size * lead); page.drawText(l, { x, y: y - size, size, font, color: col(color) }); y -= size * lead; }
    y -= gap;
  };
  const h1 = (t) => { ensure(110); y -= 6; text(t, { size: 17, font: bold, gap: 4 }); };
  const h2 = (t) => { ensure(70); y -= 8; text(t, { size: 12, font: bold, gap: 3 }); page.drawRectangle({ x: M, y: y + 2, width: W, height: 0.6, color: col(COL.line) }); y -= 4; };
  const box = (t, { bg, fg, size = 11, pad = 10, font = bold }) => {
    const lines = wrap(t, font, size, W - 2 * pad);
    const h = lines.length * size * 1.35 + 2 * pad;
    ensure(h + 4);
    page.drawRectangle({ x: M, y: y - h, width: W, height: h, color: col(bg) });
    let yy = y - pad;
    for (const l of lines) { page.drawText(l, { x: M + pad, y: yy - size, size, font, color: col(fg) }); yy -= size * 1.35; }
    y -= h + 8;
  };
  const table = (head, rows, widths, { size = 8.6, badgeCol = -1 } = {}) => {
    const tw = widths.reduce((a, b) => a + b, 0), sc = W / tw, ws = widths.map((w) => w * sc), pad = 4;
    const drawHead = () => {
      ensure(22);
      page.drawRectangle({ x: M, y: y - 16, width: W, height: 16, color: col(COL.head) });
      let x = M;
      head.forEach((h, i) => { page.drawText(clean(h), { x: x + pad, y: y - 11.5, size: size, font: bold, color: col(COL.ink) }); x += ws[i]; });
      y -= 16;
    };
    drawHead();
    for (const r of rows) {
      const cells = r.map((c, i) => wrap(String(c.text ?? c), (c.bold ? bold : reg), size, ws[i] - 2 * pad));
      const h = Math.max(...cells.map((l) => l.length)) * size * 1.3 + 2 * pad - 2;
      if (y - h < M + 26) { newPage(); drawHead(); }
      let x = M;
      r.forEach((c, i) => {
        if (i === badgeCol) {
          const sev = c.sev, label = SEV[sev];
          page.drawRectangle({ x: x + pad, y: y - 13, width: 30, height: 11, color: col(COL[sev]) });
          page.drawText(label, { x: x + pad + 4, y: y - 10.5, size: 7, font: bold, color: rgb(1, 1, 1) });
        } else {
          let yy = y - pad;
          for (const l of cells[i]) { page.drawText(l, { x: x + pad, y: yy - size, size, font: c.bold ? bold : reg, color: col(c.color || COL.ink) }); yy -= size * 1.3; }
        }
        x += ws[i];
      });
      page.drawRectangle({ x: M, y: y - h, width: W, height: 0.5, color: col(COL.line) });
      y -= h;
    }
    y -= 8;
  };
  const kv = (rows) => table(['', ''], rows.map(([k, v]) => [{ text: k, bold: true, color: COL.mute }, v]), [1, 2.6], { size: 9.4 });

  const s = res.summary;
  const c = ctx.meta || {};
  const exp = ctx.exposure && !ctx.exposure.refused ? ctx.exposure : null;

  // ---- Page 1: cover and verdict
  newPage();
  page.drawRectangle({ x: 0, y: A4[1] - 92, width: A4[0], height: 92, color: col(COL.navy) });
  page.drawText('SUPPLIER REPORT AUDIT PACK', { x: M, y: A4[1] - 44, size: 20, font: bold, color: rgb(1, 1, 1) });
  page.drawText('CBAM embedded-emissions report: recomputation, rule checks and evidence requests', { x: M, y: A4[1] - 64, size: 10, font: reg, color: rgb(0.85, 0.89, 0.96) });
  y = A4[1] - 92 - 18;
  if (res.synthetic) box('SYNTHETIC EXAMPLE: errors were injected on purpose. This is not a real supplier report.', { bg: COL.navy, fg: [1, 1, 1], size: 10 });
  kv([
    ['Reference', c.reference || '-'], ['Importer', c.importer || '-'], ['Supplier / installation', c.supplier || '-'],
    ['Good (CN code, origin)', `${ctx.good.cn8 || '-'} / ${ctx.good.originCountry || '-'}`], ['Reporting year (report / import)', `${ctx.good.reportingYear || '-'} / ${ctx.good.importYear || '-'}`],
    ['Prepared by', c.preparedBy || '-'], ['Generated', ctx.generatedAt], ['Law snapshot', res.snapshot], ['Report fingerprint', ctx.fingerprint ? `${ctx.fingerprint.slice(0, 32)}...` : '-'],
  ]);
  const vc = s.fail ? { bg: COL.failBg, fg: COL.fail } : s.warn ? { bg: COL.warnBg, fg: COL.warn } : { bg: COL.passBg, fg: COL.pass };
  box(s.verdict, { ...vc, size: 11.5 });
  text(`${s.fail} failed   |   ${s.warn} warnings   |   ${s.info} notes   |   ${s.pass} passed   |   ${s.received} of ${s.checklistTotal} expected items received`, { size: 9.5, color: COL.mute, gap: 8 });
  h2('What this is');
  text('An independent re-computation and rule check of the supplier report, with a trace for every number. Use it to decide what to accept, what to ask the supplier for, and where default values apply. It does not verify emissions: only an accredited verifier verifies. It is not legal advice.', { size: 9.5 });

  // ---- Decision and exposure
  h1('1. Decision');
  const top = res.findings.filter((f) => f.severity === 'fail' || f.severity === 'warn').slice(0, 4);
  text(s.fail ? 'Recommended action: do not rely on these values as actual values yet. Request the items in section 3. If the supplier cannot provide them, use the default values (with mark-up) in the declaration.'
    : s.warn ? 'Recommended action: follow up the warnings (section 3) before relying on the reported values.' : 'Recommended action: no issues found by these checks. This is not a verification.', { size: 10.5, font: bold, gap: 4 });
  if (top.length) { text('Main reasons:', { size: 9.5, color: COL.mute }); top.forEach((f) => text(`•  ${f.title}`, { size: 9.5, x: M + 8, width: W - 8 })); }
  h2('Estimated exposure: default values versus reported values');
  if (exp) {
    const d = exp.default;
    const rows = [[{ text: 'Default path', bold: true }, `${fmt5(d.see.value)} t/t`, grp(String(Number(d.certificates.value).toFixed(3))), d.cost ? money(d.cost) : '-']];
    if (exp.actual) rows.push([{ text: 'Reported values path', bold: true }, `${exp.actual.see} t/t`, grp(String(Number(exp.actual.certificates.value).toFixed(3))), exp.actual.cost ? money(exp.actual.cost) : '-']);
    table(['Path', 'SEE used', 'Certificates (est.)', 'Estimated cost'], rows, [1.3, 1, 1.2, 1.2], { size: 9.4 });
    if (exp.saving) text(`Difference if the reported values are accepted: ${grp(String(Number(exp.saving.certificates).toFixed(3)))} certificates${exp.saving.eur ? ` (${money(exp.saving.eur)})` : ''}. Valid only if the values are verified.`, { size: 9.5, font: bold, gap: 2 });
    text(`Assumptions: ${ctx.exposureInputs}. ${exp.notes.filter((n, i) => i > 0).join(' ')}`, { size: 8.6, color: COL.mute });
  } else text(ctx.exposure && ctx.exposure.refused ? `Exposure not calculated: ${ctx.exposure.refused}.` : 'Exposure not calculated: enter origin country, 8-digit CN code, import year and tonnes to include it.', { size: 9.5, color: COL.mute });

  if (ctx.decision) {
    h2('Is verification worth paying for?');
    decisionLines(ctx.decision, 'EUR', ctx.decisionYear).lines.forEach((t, i) => text(t, { size: 9.5, gap: 2, ...(i === 0 ? { font: bold } : {}) }));
    text('Your inputs: price, tonnes and verification cost. Not a verification: only an accredited verifier verifies.', { size: 8.6, color: COL.mute });
  }

  // ---- Findings
  h1('2. Findings');
  table(['', 'Check', 'Basis'], res.findings.map((f) => [{ sev: f.severity }, { text: `${f.title}${f.detail ? `\n${f.detail}` : ''}` }, { text: f.citation, color: COL.mute }]), [0.55, 3.9, 1.7], { badgeCol: 0 });

  // ---- Evidence requests
  h1('3. Evidence to request from the supplier');
  if (ctx.requests.length) { ctx.requests.forEach((r, i) => text(`${i + 1}.  ${r.text}`, { size: 9.6, gap: 2 })); h2('Suggested email (copy and edit)'); box(ctx.email, { bg: COL.head, fg: COL.ink, size: 8.8, font: reg, pad: 9 }); }
  else text('No follow-up needed from these checks.', { size: 10 });

  // ---- Recomputation, radar
  h1('4. Recomputation and trace');
  if (res.recompute) {
    const rc = res.recompute;
    kv([['Recomputed SEE (max 5 decimals)', `${fmt5(rc.see.value)} t CO2e per t`], ['Precursor mass ratio m', fmt5(rc.ratio.value)], ['Own direct emissions per tonne', fmt5(rc.own.value)]]);
    const walk = (n, d) => {
      const x = M + d * 12, w = W - d * 12;
      text(`${n.label}: ${n.inputs ? fmt5(n.value) : n.value} ${n.unit}`, { size: 8.6, font: d === 0 ? bold : reg, x, width: w });
      if (n.inputs) { text(`formula: ${n.formula}`, { size: 7.8, color: COL.mute, x, width: w }); (n.citations || []).forEach((q) => text(`basis: ${q}`, { size: 7.8, color: COL.mute, x, width: w })); n.inputs.forEach((i) => walk(i, d + 1)); }
      else text(`source: ${n.source}`, { size: 7.8, color: COL.mute, x, width: w });
    };
    h2('Calculation trace');
    walk(rc.see, 0);
  } else text('The SEE was not recomputed (inputs missing).', { size: 10 });
  h2('Materiality radar');
  if (res.radar) {
    table(['Input', 'Share of SEE', 'Error that would move SEE by 5%'], res.radar.map((r) => [{ text: r.name, bold: true }, `${r.share.mul(100).toFixed(1)}%`, `${r.breakEven.toFixed(1)}%`]), [2, 1, 1.6], { size: 9.4 });
    text('5% is the materiality level used by verifiers. Ask for evidence first where a small error is enough to matter.', { size: 8.8, color: COL.mute });
  } else text('The radar needs a recomputation.', { size: 10 });

  // ---- Method and limits
  h1('5. Method, sources and limits');
  text('Legal basis: Regulation (EU) 2023/956 (consolidated); Implementing Regulation (EU) 2025/2547 (methodology); 2026/1740 correcting the default values of 2025/2621; 2025/2620 (free allocation adjustment); 2025/2546 (verification principles, 5% materiality); Delegated Regulation (EU) 2025/2551 (accreditation and verification). Explanations: Commission Guidance Nos. 2, 3, 4, 5d and 5e (non-binding).', { size: 9, gap: 4 });
  text(`Data snapshot ${res.snapshot}. Dataset fingerprints: ${Object.entries(ctx.datasets || {}).filter(([k]) => ['default_values.json', 'benchmarks.json', 'standard_factors.json', 'markups.json', 'cbam_factor.json'].includes(k)).map(([k, v]) => `${k.replace('.json', '')} ${v.slice(0, 10)}`).join(', ')}.`, { size: 8.4, color: COL.mute, gap: 4 });
  text('Limits and assumptions:', { size: 9.4, font: bold });
  ['Free-allocation correction factor (CSCF): 1.0 for 2026-2030 under Implementing Decision (EU) 2026/1862; for later years the preliminary 1.0 is used until published.', 'Mark-up rounding is performed by the CBAM Registry; exact values are shown.', 'The carbon price paid in the origin country is not deducted.', 'Rounding tolerance for "reproduces within rounding" is an assumption: 1.5 units of the last reported decimal.', 'Verifier accreditation and report validity are confirmed by the user, not by the tool.', 'Negative certificate counts are shown as zero (open point).'].forEach((t) => text(`•  ${t}`, { size: 8.8, x: M + 8, width: W - 8 }));
  y -= 4;
  text('Independence: this report is produced by software. It is not a verifier, has no relationship with any verifier, and does not verify or certify emissions.', { size: 8.8, gap: 3 });
  text('Reproduce: re-enter the inputs in the tool under the same law snapshot; the fingerprint is the SHA-256 of the canonical input record plus the snapshot id.', { size: 8.4, color: COL.mute });
  text(`Fingerprint: ${ctx.fingerprint || '-'}`, { size: 7.4, color: COL.mute });

  // ---- Footer on every page
  const pages = pdf.getPages();
  pages.forEach((p, i) => {
    p.drawRectangle({ x: M, y: M - 4, width: W, height: 0.5, color: col(COL.line) });
    p.drawText(clean(`Prepared for verification, not a verification statement  |  ${ctx.fingerprint ? ctx.fingerprint.slice(0, 12) : ''}  |  Page ${i + 1} of ${pages.length}`), { x: M, y: M - 16, size: 7.6, font: reg, color: col(COL.mute) });
  });
  return pdf.save();
}

// ===== app/ui.js =====
// Browser UI. All calculation lives in packages/engine; this file only reads inputs, calls the engine and draws results.

const $ = (id) => document.getElementById(id);
const el = (tag, attrs = {}, ...kids) => {
  const n = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) { if (k === 'class') n.className = v; else n.setAttribute(k, v); }
  for (const k of kids.flat()) n.append(k instanceof Node ? k : document.createTextNode(String(k)));
  return n;
};
const fetchJson = async (url) => { const r = await fetch(url); if (!r.ok) throw new Error(`${url}: ${r.status}`); return r.json(); };

const num = (v) => String(v).trim().replace(',', '.');
const isDec = (v) => /^\d+(\.\d+)?$/.test(v);
const group = (s) => s.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
function fmt(dec, places) {
  const s = D(dec).toFixed(places);
  const neg = s.startsWith('-');
  const [i, f] = (neg ? s.slice(1) : s).split('.');
  return (neg ? '-' : '') + group(i) + (f ? '.' + f : '');
}

let snap;

function showError(target, msg) { target.replaceChildren(el('div', { class: 'error', role: 'alert' }, msg)); }

function traceNode(n) {
  if (!n.inputs) return el('div', { class: 'trace' }, `${n.label}: ${n.value} ${n.unit}`, el('small', {}, `source: ${n.source}`));
  const d = el('details', { class: 'trace' }, el('summary', {}, `${n.label}: ${fmt(n.value, 5)} ${n.unit}`),
    el('small', {}, `formula: ${n.formula}`), ...(n.citations || []).map((c) => el('small', {}, `basis: ${c}`)), ...(n.note ? [el('small', {}, n.note)] : []));
  n.inputs.forEach((i) => d.append(traceNode(i)));
  return d;
}

function kv(rows) { return el('dl', { class: 'kv' }, ...rows.flatMap(([k, v]) => [el('dt', {}, k), el('dd', {}, v)])); }

function download(name, obj) {
  const a = el('a', { href: URL.createObjectURL(new Blob([JSON.stringify(obj, null, 2)], { type: 'application/json' })), download: name });
  document.body.append(a); a.click(); a.remove();
}

function actions(payload, filename) {
  return el('div', { class: 'row' },
    Object.assign(el('button', { type: 'button' }, 'Print / save as PDF'), { onclick: () => window.print() }),
    Object.assign(el('button', { type: 'button' }, 'Download JSON'), { onclick: () => download(filename, payload) }));
}

async function onExposure(e) {
  e.preventDefault();
  const out = $('out-exposure');
  const country = $('x-country').value.trim();
  const cn8 = $('x-cn').value.replace(/\s/g, '');
  const year = Number($('x-year').value);
  const mass = num($('x-mass').value), price = num($('x-price').value), asee = num($('x-asee').value), asefa = num($('x-asefa').value);
  if (!country) return showError(out, 'Choose a country from the list.');
  if (!isDec(mass)) return showError(out, 'Enter the mass in tonnes, for example 100.');
  if (price && !isDec(price)) return showError(out, 'The price must be a number.');
  if ((asee && !isDec(asee)) || (asefa && !isDec(asefa))) return showError(out, 'Supplier values must be numbers.');
  if (!(await ensureCountry(snap, country))) return showError(out, `No default-value table for "${country}". Pick a name from the list, or leave it to use "Other countries".`);
  const r = exposureCase(snap, { country, cn8, year, massT: mass, priceEur: price || undefined, actual: asee ? { see: asee, sefa: asefa } : undefined });
  if (r.refused) return showError(out, `Cannot calculate: ${r.refused}.`);
  const d = r.default;
  const cards = [el('div', { class: 'card' }, el('h3', {}, 'On default values'),
    kv([['Default SEE incl. mark-up', `${fmt(d.see.value, 5)} t/t`], ['Free allocation (SEFA)', `${fmt(d.sefa.value, 5)} t/t`],
      ['Certificates (estimate)', fmt(d.certificates.value, 3)], ...(d.cost ? [['Estimated cost', `€ ${fmt(d.cost, 2)}`]] : []),
      ['Route / benchmark', `${d.route || 'n/a'} / ${d.chainBenchmark.value}`], ['Origin used', d.country]]))];
  if (r.actual) cards.push(el('div', { class: 'card' }, el('h3', {}, 'On the supplier\'s values'),
    kv([['SEE / SEFA', `${r.actual.see} / ${r.actual.sefa}`], ['Certificates (estimate)', fmt(r.actual.certificates.value, 3)], ...(r.actual.cost ? [['Estimated cost', `€ ${fmt(r.actual.cost, 2)}`]] : [])]),
    el('p', { class: 'good' }, `Difference: ${fmt(r.saving.certificates, 3)} certificates${r.saving.eur ? ` (€ ${fmt(r.saving.eur, 2)})` : ''}`)));
  const trace = el('div', { class: 'card' }, el('h3', {}, 'Trace'), traceNode(d.see), traceNode(d.sefa), traceNode(d.certificates), ...(r.actual ? [traceNode(r.actual.certificates)] : []));
  out.replaceChildren(...cards, ...r.notes.map((n) => el('p', { class: 'note' }, n)), trace, actions({ tool: 'importer-exposure', ...r }, `cbam-exposure-${r.snapshot}.json`));
}

function onSee(e) {
  e.preventDefault();
  const out = $('out-see');
  const v = Object.fromEntries(['s-al', 's-cons', 's-psee', 's-energy'].map((id) => [id, num($(id).value)]));
  if (Object.values(v).some((x) => !isDec(x)) || D(v['s-al']).isZero()) return showError(out, 'Fill in every number field (activity level must be above zero).');
  const fuel = fuelFactor(snap, $('s-fuel').value);
  if (fuel.refused) return showError(out, fuel.refused);
  const ratio = precursorMassRatio({ id: 'm', consumedT: v['s-cons'], activityLevelT: v['s-al'] });
  const own = directFromEnergy({ id: 'own', energyGJPerT: v['s-energy'], efTCO2PerTJ: fuel.ef.toString(), factorRef: fuel.ref });
  const see = seeComplexGood({ id: 'see', own, precursors: [{ name: 'precursor', ratio, see: v['s-psee'], seeSource: $('s-psrc').value || 'operator-supplied' }] });
  const term = D(ratio.value).mul(v['s-psee']);
  const share = term.div(see.value, 6).mul(100).toFixed(0);
  out.replaceChildren(el('div', { class: 'card' }, el('h3', {}, 'Result'),
    kv([['SEE (legal precision, max 5 decimals)', `${reportSEE(D(see.value))} t CO₂e/t`], ['Precursor share of SEE', `${share}%`], ['Precursor mass ratio m', fmt(ratio.value, 5)], ['Own direct per tonne', fmt(own.value, 5)]])),
    el('p', { class: 'note' }, 'The Commission guidance tables round intermediate values to 3 decimals, so printed examples can differ in the third decimal.'),
    el('div', { class: 'card' }, el('h3', {}, 'Trace'), traceNode(see)),
    actions({ tool: 'fabricator-see', snapshot: snap.id, result: see }, `cbam-see-${snap.id}.json`));
}

function loadExample() {
  $('s-al').value = '17000'; $('s-cons').value = '20000'; $('s-psee').value = '1.567'; $('s-energy').value = '3.5';
  $('s-psrc').value = 'Guidance 5d, Example 1 (rod producer, verified report)'; $('s-fuel').value = 'Natural gas';
}


// ---- Supplier report audit tab ----
const AUDIT_FIELDS = [['a-opinion', 'verification.opinion'], ['a-accred', 'verification.accreditation'], ['a-sector', 'verification.sectorCovered'],
  ['a-origin', 'good.originCountry'], ['a-cn', 'good.cn8'], ['a-route', 'good.route'], ['a-year', 'good.reportingYear'], ['a-import', 'good.importYear'],
  ['a-al', 'good.activityLevelT'], ['a-fuel', 'good.fuel'], ['a-energy', 'good.energyGJperT'], ['a-see', 'good.seeDirectReported'],
  ['a-indirect', 'good.seeIndirectReported'], ['a-sefa', 'good.sefaReported'], ['a-p-cons', 'precursor.consumedT'], ['a-p-see', 'precursor.seeReported'],
  ['a-p-src', 'precursor.source'], ['a-p-origin', 'precursor.originCountry'], ['a-p-ref', 'precursor.verificationRef'], ['a-p-year', 'precursor.periodYear'],
  ['a-p-m', 'precursor.mReported'], ['a-al1', 'aluminium.scrapPerT'], ['a-al2', 'aluminium.preConsumerPct'], ['a-al3', 'aluminium.alloyPct'],
  ['a-ref', 'case.reference'], ['a-importer', 'case.importer'], ['a-supplier', 'case.supplier'], ['a-by', 'case.preparedBy'], ['a-mass', 'case.massT'], ['a-price', 'case.priceEur'], ['a-vcost', 'case.verifyEur']];
const NUMERIC = new Set(['a-al', 'a-energy', 'a-see', 'a-indirect', 'a-sefa', 'a-p-cons', 'a-p-see', 'a-p-m', 'a-al1', 'a-al2', 'a-al3', 'a-mass', 'a-price', 'a-vcost']);
const chkBoxes = {};
let loadedMeta = null;   // keeps the sample's label and SYNTHETIC flag until the user edits the form
const getPath = (o, path) => path.split('.').reduce((a, k) => (a == null ? undefined : a[k]), o);
const setPath = (o, path, v) => { const ks = path.split('.'); let t = o; ks.slice(0, -1).forEach((k) => { t = t[k] = t[k] || {}; }); t[ks.at(-1)] = v; };

function fillAudit(rep) {
  for (const [id, path] of AUDIT_FIELDS) $(id).value = getPath(rep, path) ?? '';
  $('a-p-on').value = rep.precursor && rep.precursor.present ? 'yes' : 'no';
  for (const c of CHECKLIST) chkBoxes[c.id].checked = Boolean(rep.checklist && rep.checklist[c.id]);
  loadedMeta = rep.meta || null;
  $('out-audit').replaceChildren();
}

function readAudit() {
  const rep = { meta: loadedMeta || { label: 'Report entered in the app', synthetic: false }, checklist: {} };
  for (const [id, path] of AUDIT_FIELDS) setPath(rep, path, NUMERIC.has(id) ? num($(id).value) : $(id).value.trim());
  rep.precursor.present = $('a-p-on').value === 'yes';
  for (const c of CHECKLIST) rep.checklist[c.id] = Boolean(chkBoxes[c.id].checked);
  return rep;
}

// Verify-or-default for the audited report: only when origin, CN code, tonnes, price and a verification cost are all entered.
function auditDecision(rep) {
  const c = rep.case || {}, g = rep.good || {};
  if (!/^\d{8}$/.test(g.cn8 || '') || !g.originCountry || !isDec(c.massT || '') || !isDec(c.priceEur || '') || !isDec(c.verifyEur || '')) return null;
  const r = verifyOrDefault(snap, { country: g.originCountry, cn8: g.cn8, massT: c.massT, priceEur: c.priceEur, verifyEur: c.verifyEur,
    supplierSee: g.seeDirectReported || undefined, sefaActual: g.sefaReported || undefined });
  return r.refused ? null : r;
}

async function makePdf(rep, res) {
  if (!globalThis.PDFLib) throw new Error('the PDF library did not load (check that pdf-lib.min.js is next to index.html)');
  const c = rep.case || {}, g = rep.good || {};
  const requests = evidenceRequests(res);
  const email = supplierEmail({ requests, reference: c.reference, importer: c.importer, supplier: c.supplier, preparedBy: c.preparedBy });
  let exposure = null, exposureInputs = '';
  if (/^\d{8}$/.test(g.cn8 || '') && g.originCountry && isDec(c.massT || '') && Number(g.importYear) >= 2026) {
    exposure = exposureCase(snap, { country: g.originCountry, cn8: g.cn8, year: Number(g.importYear), massT: c.massT, priceEur: c.priceEur || undefined,
      actual: g.seeDirectReported && g.sefaReported ? { see: g.seeDirectReported, sefa: g.sefaReported } : undefined });
    exposureInputs = `${c.massT} t, import year ${g.importYear}${c.priceEur ? `, certificate price EUR ${c.priceEur} per t (your assumption)` : ', no price entered'}`;
  }
  const fp = await fingerprint(rep, snap.id);
  const bytes = await buildAuditPdf(globalThis.PDFLib, res, { meta: c, good: g, exposure, exposureInputs, decision: auditDecision(rep), decisionYear: Number(g.importYear), requests, email, fingerprint: fp,
    generatedAt: new Date().toISOString().slice(0, 10), datasets: snap.manifest.datasets });
  return { bytes, fp };
}

function downloadBytes(name, bytes, type) {
  const a = el('a', { href: URL.createObjectURL(new Blob([bytes], { type })), download: name });
  document.body.append(a); a.click(); a.remove();
}

async function onAudit(e) {
  e.preventDefault();
  const out = $('out-audit');
  const rep = readAudit();
  const res = auditReport(snap, rep);
  const status = el('p', { class: 'note', role: 'status' });
  const safe = String((rep.case && rep.case.reference) || 'report').replace(/[^A-Za-z0-9_-]+/g, '-');
  const pdfBtn = el('button', { type: 'button', class: 'primary', id: 'a-pdf' }, 'Download PDF report');
  pdfBtn.onclick = async () => {
    status.textContent = 'Preparing the PDF…';
    try { const { bytes, fp } = await makePdf(rep, res); downloadBytes(`CBAM-audit-${safe}.pdf`, bytes, 'application/pdf'); status.textContent = `PDF ready (fingerprint ${fp.slice(0, 12)}).`; }
    catch (err) { status.textContent = `Could not create the PDF: ${err.message}`; }
  };
  const jsonBtn = el('button', { type: 'button', id: 'a-json' }, 'Download data (JSON)');
  jsonBtn.onclick = () => download(`cbam-audit-${safe}.json`, { tool: 'supplier-report-audit', input: rep, result: res });
  const holder = el('div', { id: 'a-result' });
  holder.innerHTML = renderAuditBody(res);
  const dec = auditDecision(rep);
  if (dec) { const dl = decisionLines(dec, '€', Number(rep.good.importYear)); holder.append(el('div', { class: 'card' }, el('h3', {}, 'Is verification worth paying for?'), ...dl.lines.map((t) => el('p', {}, t)))); }
  out.replaceChildren(el('div', { class: 'row' }, pdfBtn, jsonBtn), status, holder);
}

const dLo = (a) => a.reduce((p, q) => (q.lt(p) ? q : p)), dHi = (a) => a.reduce((p, q) => (q.gt(p) ? q : p));
const dRng = (a, f) => (dLo(a).eq(dHi(a)) ? f(dLo(a)) : `${f(dLo(a))} to ${f(dHi(a))}`);
const dMoney = (cur, d) => `${cur} ${fmt(abs(d), 0)}`, dSigned = (cur, d) => `${d.lt(0) ? '-' : '+'}${dMoney(cur, d)}`;

// Plain-language reading of a verifyOrDefault result for one year. Shared by the screen (cur '€') and the PDF (cur 'EUR').
function decisionLines(r, cur, year) {
  const ok = r.rows.filter((x) => !x.refused), y = ok.find((x) => x.year === year) || ok[0];
  const V = D(r.inputs.verifyEur), see = r.inputs.supplierSee, lines = [];
  let pass = false;
  if (see) {
    const nets = y.scen.map((s) => s.net); pass = dLo(nets).gt(0);
    lines.push(`At a supplier SEE of ${see} t/t, verification ${pass ? 'pays' : dHi(nets).gt(0) ? 'may or may not pay' : 'does not pay'} in ${y.year}: net ${dRng(nets, (d) => dSigned(cur, d))} after a ${dMoney(cur, V)} cost.`);
  } else if (y.canPay) {
    pass = true;
    lines.push(`Verification (${dMoney(cur, V)} a year) pays for itself in ${y.year} only if the supplier's real SEE is below ${dRng(y.scen.map((s) => D(s.breakEven.value)), (d) => fmt(d, 2))} t/t. The default is ${fmt(y.see, 2)}.`);
  } else lines.push(`At ${dMoney(cur, V)} a year, verification cannot pay back in ${y.year}: even zero certificates would save only ${dMoney(cur, y.cost)}.`);
  if (y.swing) lines.push(`The supplier's free allocation (SEFA) swings this by up to ${dMoney(cur, y.swing)} a year. Get the SEFA from the supplier before paying for verification.`);
  else if (y.scen.length === 1 && !r.inputs.sefaActual) lines.push('No process benchmark is published for this route, so the result assumes the default free allocation. Get the supplier\'s SEFA.');
  return { lines, pass };
}

async function onDecide(e) {
  e.preventDefault();
  const out = $('out-decide');
  const country = $('d-country').value.trim(), cn8 = $('d-cn').value.replace(/\s/g, '');
  const mass = num($('d-mass').value), price = num($('d-price').value), vcost = num($('d-vcost').value), see = num($('d-see').value), sefa = num($('d-sefa').value);
  if (!country) return showError(out, 'Choose a country from the list.');
  if (!isDec(mass) || !isDec(price) || !isDec(vcost)) return showError(out, 'Enter tonnes, certificate price and verification cost as numbers.');
  if ((see && !isDec(see)) || (sefa && !isDec(sefa))) return showError(out, 'The supplier values must be numbers.');
  if (!(await ensureCountry(snap, country))) return showError(out, `No default-value table for "${country}". Pick a name from the list.`);
  const r = verifyOrDefault(snap, { country, cn8, massT: mass, priceEur: price, verifyEur: vcost, supplierSee: see || undefined, sefaActual: sefa || undefined });
  if (r.refused) return showError(out, `Cannot calculate: ${r.refused}.`);
  const d = decisionLines(r, '€'), ok = r.rows.filter((x) => !x.refused), y1 = ok[0];
  const maxCost = ok.reduce((m, x) => (x.cost.gt(m) ? x.cost : m), D(0));
  const head = ['Year', 'Default cost', 'Pays back if supplier SEE below', ...(see ? ['Net at your SEE'] : [])];
  const table = el('div', { class: 'tblwrap' }, el('table', {}, el('thead', {}, el('tr', {}, ...head.map((h) => el('th', {}, h)))),
    el('tbody', {}, ...r.rows.map((x) => x.refused ? el('tr', {}, el('td', {}, x.year), el('td', { colspan: String(head.length - 1) }, `n/a: ${x.refused}`)) :
      el('tr', {}, el('td', {}, x.year),
        el('td', { class: 'num' }, `€ ${fmt(x.cost, 0)}`, el('span', { class: 'bar', style: `width:${maxCost.isZero() ? 0 : x.cost.div(maxCost, 4).mul(100).toFixed(0)}%` })),
        el('td', { class: 'num' }, x.canPay ? dRng(x.scen.map((s) => D(s.breakEven.value)), (n) => fmt(n, 3)) : 'never'),
        ...(see ? [el('td', { class: 'num' }, dRng(x.scen.map((s) => s.net), (n) => dSigned('€', n)))] : []))))));
  const payload = { tool: 'verify-or-default', snapshot: r.snapshot, inputs: r.inputs, notes: r.notes,
    rows: r.rows.map((x) => x.refused ? x : { year: x.year, defaultSee: x.see.toString(), defaultSefa: x.sefa.toString(), defaultCostEur: x.cost.toString(),
      scenarios: x.scen.map((s) => ({ label: s.label, sefa: s.sefa.toString(), breakEvenSee: s.breakEven ? s.breakEven.value : null, ...(s.net ? { savingEur: s.saving.toString(), netEur: s.net.toString() } : {}) })) }) };
  out.replaceChildren(el('div', { class: 'verdict ' + (d.pass ? 'v-pass' : 'v-warn') }, ...d.lines.map((t) => el('p', {}, t))), table, ...r.notes.map((n) => el('p', { class: 'note' }, n)),
    el('div', { class: 'card' }, el('h3', {}, `Trace (${y1.year})`), ...y1.scen.filter((s) => s.breakEven).map((s) => traceNode(s.breakEven)), traceNode(y1.trace.see), traceNode(y1.trace.sefa), traceNode(y1.trace.certificates)),
    actions(payload, `cbam-verify-or-default-${r.snapshot}.json`));
}

function tabs() {
  document.querySelectorAll('.tabs button').forEach((b) => b.addEventListener('click', () => {
    document.querySelectorAll('.tabs button').forEach((x) => x.setAttribute('aria-selected', String(x === b)));
    document.querySelectorAll('.panel').forEach((p) => { p.hidden = p.id !== `tab-${b.dataset.tab}`; });
  }));
}

async function init() {
  tabs();
  try {
    snap = await loadWebSnapshot(fetchJson);
  } catch (err) {
    $('snapshot').textContent = 'Could not load the law data. Serve this folder over HTTP (for example GitHub Pages) rather than opening the file directly.';
    return;
  }
  $('snapshot').textContent = `Law snapshot ${snap.id} · ${snap.countryIndex.length} countries · built from the official files`;
  $('countries').replaceChildren(...snap.countryIndex.map((c) => el('option', { value: c.name })));
  $('s-fuel').replaceChildren(...snap.factors.tables.table_1.records.filter((r) => r.ef_t_co2_per_tj).map((r) => el('option', { value: r.name }, r.name)));
  $('s-fuel').value = 'Natural gas';
  $('a-fuel').replaceChildren(...snap.factors.tables.table_1.records.filter((r) => r.ef_t_co2_per_tj).map((r) => el('option', { value: r.name }, r.name)));
  $('a-checklist').replaceChildren(...CHECKLIST.map((c) => { const box = el('input', { type: 'checkbox' }); chkBoxes[c.id] = box; return el('label', { class: 'chk' }, box, ` ${c.text} (${c.ref})`); }));
  $('limits').replaceChildren(...[
    'Free-allocation correction factor (CSCF) is 1.0 for 2026-2030 (Implementing Decision (EU) 2026/1862); later years use the preliminary 1.0.',
    'Mark-up rounding is done by the CBAM Registry; exact values are shown.',
    'Carbon price paid in the origin country is not deducted.',
    'Negative certificate counts are shown as zero (open question).',
    'Verify-or-default shows free-allocation bounds when the supplier SEFA is missing; price, tonnes and verification cost are your inputs, held constant across years.',
    'Integrated blast-furnace plants, heat/CHP flows, CCS and primary aluminium PFC are not supported yet.',
    'The workbook-to-law cross-check is partial until Implementing Regulation 2025/2621 is loaded.',
  ].map((t) => el('li', {}, t)));
  $('manifest').textContent = JSON.stringify({ snapshot: snap.id, datasets: snap.manifest.datasets, sources: snap.manifest.sources_hashed + ' source files hashed' }, null, 1);
  $('form-decide').addEventListener('submit', onDecide);
  $('form-exposure').addEventListener('submit', onExposure);
  $('form-see').addEventListener('submit', onSee);
  $('s-example').addEventListener('click', loadExample);
  $('form-audit').addEventListener('submit', onAudit);
  $('form-audit').addEventListener('input', () => { loadedMeta = null; });
  $('a-load-clean').addEventListener('click', () => fillAudit(SAMPLE_CLEAN));
  $('a-load-flawed').addEventListener('click', () => fillAudit(SAMPLE_FLAWED));
}
init();
